mapper.select:
SELECT
-- 卡口门禁是否有数据
(SELECT COUNT(*) FROM shipingtaishujuzhongxin.kkmjxx WHERE deleted = '0'

    AND park_code = #{parkCode}


    AND countycode = #{countycode}

) as kkmjCount,
-- 访客信息是否有数据
(SELECT COUNT(*) FROM shipingtaishujuzhongxin.fkxx WHERE deleted = '0'

    AND park_code = #{parkCode}


    AND countycode = #{countycode}

) as fkxxCount,
-- 危化品车辆信息是否有数据
(SELECT COUNT(*) FROM shipingtaishujuzhongxin.whpclxx WHERE deleted = '0'

    AND park_code = #{parkCode}


    AND countycode = #{countycode}

) as whpclCount,
-- 其他车辆信息是否有数据
(SELECT COUNT(*) FROM shipingtaishujuzhongxin.qtclxx WHERE deleted = '0'

    AND park_code = #{parkCode}


    AND countycode = #{countycode}

) as qtclCount,
-- 危化品运输车辆停车场信息是否有数据
(SELECT COUNT(*) FROM shipingtaishujuzhongxin.whpyscltccxx WHERE deleted = '0'

    AND park_code = #{parkCode}


    AND countycode = #{countycode}

) as tccCount,
-- 车辆实时通行数据是否有数据
(SELECT COUNT(*) FROM shipingtaishujuzhongxin.clsstx WHERE deleted = '0'

    AND park_code = #{parkCode}


    AND countycode = #{countycode}

) as clsstxCount,
-- 人员实时通行数据是否有数据
(SELECT COUNT(*) FROM shipingtaishujuzhongxin.rysstxsj WHERE deleted = '0'

    AND park_code = #{parkCode}


    AND countycode = #{countycode}

) as rysstxCount,
-- 人员实时定位是否有数据
(SELECT COUNT(*) FROM shipingtaishujuzhongxin.ryssdw WHERE deleted = '0'

    AND park_code = #{parkCode}


    AND countycode = #{countycode}

) as ryssdwCount,
-- 危化品车辆实时定位是否有数据
(SELECT COUNT(*) FROM shipingtaishujuzhongxin.whpclssdw WHERE deleted = '0'

    AND park_code = #{parkCode}


    AND countycode = #{countycode}

) as whpclssdwCount,
-- 报警数据是否有数据
(SELECT COUNT(*) FROM shipingtaishujuzhongxin.sbbjsj WHERE deleted = '0'

    AND park_code = #{parkCode}


    AND countycode = #{countycode}

) as sbbjsjCount

SELECT CASE alarm_type WHEN '1' THEN '入侵报警' WHEN '2' THEN '超速报警' WHEN '3' THEN '求救报警' WHEN '4' THEN '滞留报警' ELSE '其他' END as name, COUNT(*) as value FROM shipingtaishujuzhongxin.sbbjsj
deleted = '0'
AND park_code = #{parkCode}
AND countycode = #{countycode}
GROUP BY alarm_type

SELECT
(SELECT COUNT(*) FROM shipingtaishujuzhongxin.kkmjxx WHERE deleted = '0'

    AND park_code = #{parkCode}


    AND countycode = #{countycode}

) as gateCount,
(SELECT COUNT(*) FROM shipingtaishujuzhongxin.whpclxx WHERE deleted = '0'

    AND park_code = #{parkCode}


    AND countycode = #{countycode}

) as hazardousVehicleCount,
(SELECT COUNT(*) FROM shipingtaishujuzhongxin.qtclxx WHERE deleted = '0'

    AND park_code = #{parkCode}


    AND countycode = #{countycode}

) as otherVehicleCount,
(SELECT COUNT(*) FROM shipingtaishujuzhongxin.fkxx WHERE deleted = '0'

    AND park_code = #{parkCode}


    AND countycode = #{countycode}

) as visitorCount

SELECT kkmj.has_kkmj, fk.has_fkxx, whpcl.has_whpcl, qtcl.has_qtcl, tcc.has_tcc, clsstx.has_clsstx, rysstx.has_rysstx, ryssdw.has_ryssdw, whpclssdw.has_whpclssdw, sbbjsj.has_sbbjsj,
kkmj.gateCount, whpcl.hazardousVehicleCount, qtcl.otherVehicleCount, fk.visitorCount,
traffic.totalVehicleTraffic, traffic.generalCargoCount, traffic.hazardousTransportCount, traffic.smallVehicleCount, traffic.emergencyVehicleCount,
personnel.registeredPersonnelCount, personnel.visitorPersonnelCount,
alarm.alarm_intrusion, alarm.alarm_speed, alarm.alarm_help, alarm.alarm_stay, alarm.alarm_other FROM (SELECT COUNT(*) > 0 AS has_kkmj, COUNT(*) AS gateCount FROM shipingtaishujuzhongxin.kkmjxx WHERE deleted = '0' AND park_code IN
#{code}
) kkmj,
(SELECT COUNT(*) > 0 AS has_fkxx, COUNT(*) AS visitorCount FROM shipingtaishujuzhongxin.fkxx WHERE deleted = '0' AND park_code IN
#{code}
) fk,
(SELECT COUNT(*) > 0 AS has_whpcl, COUNT(*) AS hazardousVehicleCount FROM shipingtaishujuzhongxin.whpclxx WHERE deleted = '0' AND park_code IN
#{code}
) whpcl,
(SELECT COUNT(*) > 0 AS has_qtcl, COUNT(*) AS otherVehicleCount FROM shipingtaishujuzhongxin.qtclxx WHERE deleted = '0' AND park_code IN
#{code}
) qtcl,
(SELECT COUNT(*) > 0 AS has_tcc FROM shipingtaishujuzhongxin.whpyscltccxx WHERE deleted = '0' AND park_code IN
#{code}
) tcc,
(SELECT COUNT(*) > 0 AS has_clsstx FROM shipingtaishujuzhongxin.clsstx WHERE deleted = '0' AND park_code IN
#{code}
) clsstx,
(SELECT COUNT(*) > 0 AS has_rysstx FROM shipingtaishujuzhongxin.rysstxsj WHERE deleted = '0' AND park_code IN
#{code}
) rysstx,
(SELECT COUNT(*) > 0 AS has_ryssdw FROM shipingtaishujuzhongxin.ryssdw WHERE deleted = '0' AND park_code IN
#{code}
) ryssdw,
(SELECT COUNT(*) > 0 AS has_whpclssdw FROM shipingtaishujuzhongxin.whpclssdw WHERE deleted = '0' AND park_code IN
#{code}
) whpclssdw,
(SELECT COUNT(*) > 0 AS has_sbbjsj FROM shipingtaishujuzhongxin.sbbjsj WHERE deleted = '0' AND park_code IN
#{code}
) sbbjsj,
-- 车辆通行统计：防止 SUM 返回 NULL --> (SELECT COUNT(*) AS totalVehicleTraffic, COALESCE(SUM(vehicle_type = '1'), 0) AS generalCargoCount, COALESCE(SUM(vehicle_type = '2'), 0) AS hazardousTransportCount, COALESCE(SUM(vehicle_type = '3'), 0) AS smallVehicleCount, COALESCE(SUM(vehicle_type = '4'), 0) AS emergencyVehicleCount FROM shipingtaishujuzhongxin.clsstx WHERE deleted = '0' AND park_code IN
#{code}
AND pass_time >= #{startTime} AND pass_time < #{endTime} ) traffic,
-- 人员通行统计：防止 SUM 返回 NULL --> (SELECT COALESCE(SUM(staff_type = '1'), 0) AS registeredPersonnelCount, COALESCE(SUM(staff_type = '2'), 0) AS visitorPersonnelCount FROM shipingtaishujuzhongxin.rysstxsj WHERE deleted = '0' AND park_code IN
#{code}
AND pass_time >= #{startTime} AND pass_time < #{endTime} ) personnel,
-- 报警统计：防止 SUM 返回 NULL --> (SELECT COALESCE(SUM(alarm_type = '1'), 0) AS alarm_intrusion, COALESCE(SUM(alarm_type = '2'), 0) AS alarm_speed, COALESCE(SUM(alarm_type = '3'), 0) AS alarm_help, COALESCE(SUM(alarm_type = '4'), 0) AS alarm_stay, COALESCE(SUM(alarm_type NOT IN ('1','2','3','4') OR alarm_type IS NULL), 0) AS alarm_other FROM shipingtaishujuzhongxin.sbbjsj WHERE deleted = '0' AND park_code IN
#{code}
) alarm

SELECT p.park_code, IF(IFNULL(t1.has_kkmj, 0), 1, 0) + IF(IFNULL(t2.has_fkxx, 0), 1, 0) + IF(IFNULL(t3.has_whpcl, 0), 1, 0) + IF(IFNULL(t4.has_qtcl, 0), 1, 0) + IF(IFNULL(t5.has_tcc, 0), 1, 0) + IF(IFNULL(t8.has_ryssdw, 0), 1, 0) + IF(IFNULL(t9.has_whpclssdw, 0), 1, 0) AS staticModuleCount, IFNULL(t1.gateCount, 0) AS gateCount, IFNULL(t3.hazardousVehicleCount, 0) AS hazardousVehicleCount, IFNULL(t4.otherVehicleCount, 0) AS otherVehicleCount, IFNULL(t2.visitorCount, 0) AS visitorCount FROM (
SELECT #{code} AS park_code
) p LEFT JOIN ( SELECT park_code, (COUNT(*) > 0) AS has_kkmj, COUNT(*) AS gateCount FROM shipingtaishujuzhongxin.kkmjxx WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code ) t1 ON p.park_code = t1.park_code LEFT JOIN ( SELECT park_code, (COUNT(*) > 0) AS has_fkxx, COUNT(*) AS visitorCount FROM shipingtaishujuzhongxin.fkxx WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code ) t2 ON p.park_code = t2.park_code LEFT JOIN ( SELECT park_code, (COUNT(*) > 0) AS has_whpcl, COUNT(*) AS hazardousVehicleCount FROM shipingtaishujuzhongxin.whpclxx WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code ) t3 ON p.park_code = t3.park_code LEFT JOIN ( SELECT park_code, (COUNT(*) > 0) AS has_qtcl, COUNT(*) AS otherVehicleCount FROM shipingtaishujuzhongxin.qtclxx WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code ) t4 ON p.park_code = t4.park_code LEFT JOIN ( SELECT park_code, (COUNT(*) > 0) AS has_tcc FROM shipingtaishujuzhongxin.whpyscltccxx WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code ) t5 ON p.park_code = t5.park_code LEFT JOIN ( SELECT park_code, (COUNT(*) > 0) AS has_ryssdw FROM shipingtaishujuzhongxin.ryssdw WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code ) t8 ON p.park_code = t8.park_code LEFT JOIN ( SELECT park_code, (COUNT(*) > 0) AS has_whpclssdw FROM shipingtaishujuzhongxin.whpclssdw WHERE deleted = '0' AND park_code IN #{c} GROUP BY park_code ) t9 ON p.park_code = t9.park_code

SELECT park_code, COUNT(*) AS cnt
FROM ${tableName}
WHERE deleted = '0'
AND park_code IN
#{c}
GROUP BY park_code
